#!/usr/bin/env bash
#
# frpc/start.sh — run the frp client that exposes the Antigravity web UI.
#
# frpc.toml is generated by the panel — overwrite it when you switch node or
# remote port, then run `./frpc/start.sh start`. The public URL is derived from
# that file (serverAddr + remotePort), nothing is hardcoded here.
#
# Usage:
#   frpc/start.sh            start (idempotent)
#   frpc/start.sh status
#   frpc/start.sh stop
#
# Runs inside a tmux session so it survives the SSH session.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CONFIG="$HERE/frpc.toml"
SESSION="${SESSION:-antigravity-frpc}"
LOG="$HERE/frpc.log"
PIDFILE="$HERE/frpc.pid"

log() { printf '[frpc] %s\n' "$*"; }

# Public URL implied by the current frpc.toml (serverAddr + remotePort).
public_url() {
  local addr port
  addr="$(sed -n 's/^serverAddr *= *"\([^"]*\)".*/\1/p' "$CONFIG" | head -1)"
  port="$(sed -n 's/^remotePort *= *\([0-9]*\).*/\1/p' "$CONFIG" | head -1)"
  [ -n "$addr" ] && [ -n "$port" ] && echo "https://$addr:$port/"
}

running_pid() {
  if [ -f "$PIDFILE" ]; then
    local p; p="$(cat "$PIDFILE" 2>/dev/null || true)"
    if [ -n "$p" ] && kill -0 "$p" 2>/dev/null; then echo "$p"; return 0; fi
  fi
  # fall back to pattern match on this config only
  pgrep -f "frpc -c $CONFIG" | head -1 || true
}

case "${1:-start}" in
  start)
    [ -x "$HERE/frpc" ] || { log "ERROR: frpc binary missing in $HERE"; exit 1; }
    [ -f "$CONFIG" ] || { log "ERROR: config missing: $CONFIG"; exit 1; }
    pid="$(running_pid)"
    if [ -n "$pid" ]; then
      log "already running (pid $pid)"
      exit 0
    fi
    tmux kill-session -t "$SESSION" 2>/dev/null || true
    # 每次启动清空上一次的日志：frpc 在本地端口短暂不可用时（比如正在重启代理）
    # 会为每个进来的连接打一行 "connection refused"，堆积到 700+ 行会让人误以为隧道坏了。
    : > "$LOG"
    tmux new-session -d -s "$SESSION" -c "$HERE" \
      "'$HERE/frpc' -c '$CONFIG' 2>&1 | tee '$LOG'; echo \$\$ > '$PIDFILE'"
    sleep 3
    pid="$(running_pid)"
    if [ -n "$pid" ]; then
      log "started (pid $pid, tmux: $SESSION)"
      tail -5 "$LOG" 2>/dev/null || true
    else
      log "failed to start; log:"; tail -20 "$LOG" 2>/dev/null || true; exit 1
    fi
    ;;
  status)
    pid="$(running_pid)"
    if [ -n "$pid" ]; then
      log "running (pid $pid)"
      url="$(public_url || true)"
      log "public: ${url:-<unknown>}"
      if [ -n "$url" ]; then
        code="$(curl -sk -m 6 -o /dev/null -w '%{http_code}' "$url" || echo 000)"
        case "$code" in
          200) log "probe: 200 — 可访问" ;;
          401) log "probe: 401 — 隧道正常,需要访问令牌(见 scripts/start-mobile-web.sh token)" ;;
          *)   log "probe: $code" ;;
        esac
      fi
    else
      log "not running"
    fi
    ;;
  stop)
    pid="$(running_pid)"
    [ -n "$pid" ] && kill "$pid" 2>/dev/null || true
    tmux kill-session -t "$SESSION" 2>/dev/null || true
    rm -f "$PIDFILE"
    log "stopped"
    ;;
  *)
    echo "usage: $0 [start|stop|status]" >&2; exit 2 ;;
esac
